# email — mailbox artifact discovery: PST/OST/NST mailstores, Outlook profile
# registry traces (001f6700 = PST path value), loose .msg/.eml. Content stays.
$P=@();try{foreach($d in (Get-ChildItem 'C:\Users' -Directory -ErrorAction Stop)){foreach($rt in @((Join-Path $d.FullName 'AppData\Local\Microsoft\Outlook'),(Join-Path $d.FullName 'Documents'))){if(Test-Path $rt){foreach($f in (Get-ChildItem $rt -Recurse -Depth 2 -Include *.pst,*.ost,*.nst -File -ErrorAction SilentlyContinue)){if($P.Count -lt $Limit){$P+=[pscustomobject]@{path=$f.FullName;size=$f.Length;mtime=($f.LastWriteTimeUtc.ToString('o'))}}}}}}}catch{}
$M=@();try{$bk='HKCU:\Software\Microsoft\Windows NT\CurrentVersion\Windows Messaging Subsystem\Profiles';foreach($pf in (Get-ChildItem $bk -ErrorAction SilentlyContinue)){if($M.Count -ge $Limit){break};$refs=@();foreach($k in (Get-ChildItem $pf.PSPath -Recurse -ErrorAction SilentlyContinue)){foreach($vn in (@($k.Property) -like '*001f6700')){if($refs.Count -lt 8){$b=(Get-ItemProperty -LiteralPath $k.PSPath -Name $vn -ErrorAction SilentlyContinue).$vn;if($b -is [byte[]]){$s=[Text.Encoding]::Unicode.GetString($b).Trim([char]0);if($s){$refs+=$s}}}}}if($refs -or $M.Count -lt $Limit){$M+=[pscustomobject]@{profile=$pf.PSChildName;pst_refs=$refs}}}}catch{}
$L=@();try{foreach($d in (Get-ChildItem 'C:\Users' -Directory -ErrorAction SilentlyContinue)){foreach($sub in @('Documents','Desktop')){$rt=Join-Path $d.FullName $sub;if(Test-Path $rt){foreach($f in (Get-ChildItem $rt -Recurse -Depth 1 -Include *.msg,*.eml -File -ErrorAction SilentlyContinue)){if($L.Count -lt $Limit){$L+=[pscustomobject]@{path=$f.FullName;size=$f.Length;mtime=($f.LastWriteTimeUtc.ToString('o'))}}}}}}}catch{}
[pscustomobject]@{skill='email';host=$env:COMPUTERNAME;utc=(Get-Date).ToUniversalTime().ToString('o');mailstores=$P;outlook_profiles=$M;loose_msg_eml=$L}|ConvertTo-Json -Compress -Depth 4
